(() => {
  const STORAGE_KEY = 'todos-vanillajs';
  const ENTER_KEY = 13;
  const ESCAPE_KEY = 27;

  const $ = (sel, root) => (root || document).querySelector(sel);
  const $all = (sel, root) => Array.prototype.slice.call((root || document).querySelectorAll(sel));

  const routeFromHash = () => {
    const h = window.location.hash;
    if (h === '#/active') return 'active';
    if (h === '#/completed') return 'completed';
    return 'all';
  };

  const load = () => {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : [];
  };

  const save = () => {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  };

  const nextId = () => {
    const max = todos.reduce((m, t) => (typeof t.id === 'number' && t.id > m ? t.id : m), 0);
    return max + 1;
  };

  let todos = load();
  let filter = routeFromHash();

  const todoList = $('.todo-list');
  const newTodo = $('.new-todo');
  const main = $('#main');
  const footer = $('.footer');
  const count = $('.todo-count');
  const clearCompleted = $('.clear-completed');
  const toggleAll = $('#toggle-all');
  const filters = $all('.filters a');

  const matchesFilter = (todo) => {
    if (filter === 'active') return !todo.completed;
    if (filter === 'completed') return todo.completed;
    return true;
  };

  const indexOfLi = (li) => Array.prototype.indexOf.call(todoList.children, li);

  const buildItem = (todo) => {
    const li = document.createElement('li');
    const view = document.createElement('div');
    view.className = 'view';

    const toggle = document.createElement('input');
    toggle.className = 'toggle';
    toggle.type = 'checkbox';

    const label = document.createElement('label');

    const destroy = document.createElement('button');
    destroy.className = 'destroy';

    view.appendChild(toggle);
    view.appendChild(label);
    view.appendChild(destroy);

    const edit = document.createElement('input');
    edit.className = 'edit';

    li.appendChild(view);
    li.appendChild(edit);
    li.__todoId = todo.id;
    return li;
  };

  const updateItem = (li, todo) => {
    li.classList.toggle('completed', todo.completed);
    li.classList.remove('editing');
    li.style.display = matchesFilter(todo) ? '' : 'none';
    const toggle = li.querySelector('.toggle');
    toggle.checked = todo.completed;
    const label = li.querySelector('label');
    label.textContent = todo.title;
    const edit = li.querySelector('.edit');
    edit.value = todo.title;
  };

  /** @planks("the recorded todo-list item elements are still attached to the document") */
  const render = () => {
    // Reconcile the existing list elements in place so a reference held to a todo
    // item's <li> across an interaction stays attached, instead of replacing the list.
    const byId = new Map();
    Array.prototype.forEach.call(todoList.children, (li) => {
      byId.set(li.__todoId, li);
    });
    const kept = new Set();
    todos.forEach((todo) => {
      let li = byId.get(todo.id);
      if (!li) li = buildItem(todo);
      li.__todoId = todo.id;
      updateItem(li, todo);
      todoList.appendChild(li);
      kept.add(todo.id);
    });
    Array.prototype.slice.call(todoList.children).forEach((li) => {
      if (!kept.has(li.__todoId) && todoList.contains(li)) todoList.removeChild(li);
    });

    const active = todos.filter((t) => !t.completed).length;
    const completed = todos.length - active;

    const n = active;
    count.innerHTML = `<strong>${n}</strong> ${n === 1 ? 'item' : 'items'} left`;

    const has = todos.length > 0;
    main.hidden = !has;
    footer.hidden = !has;
    clearCompleted.hidden = completed === 0;
    toggleAll.checked = has && active === 0;

    filters.forEach((a) => {
      const href = a.getAttribute('href');
      const isSelected =
        (href === '#/active' && filter === 'active') ||
        (href === '#/completed' && filter === 'completed') ||
        (href === '#/' && filter === 'all');
      if (isSelected) a.classList.add('selected');
      else a.classList.remove('selected');
    });
  };

  const commitEdit = (edit) => {
    const li = edit.closest('li');
    const idx = indexOfLi(li);
    if (idx < 0) return;
    const title = edit.value.trim();
    if (title === '') {
      todos.splice(idx, 1);
    } else {
      todos[idx].title = title;
    }
    save();
    render();
  };

  // New todo
  newTodo.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.keyCode === ENTER_KEY) {
      const title = newTodo.value.trim();
      if (title !== '') {
        todos.push({ id: nextId(), title: title, completed: false });
        save();
      }
      newTodo.value = '';
      render();
    }
  });

  // Delegated list interactions
  todoList.addEventListener('change', (e) => {
    const toggle = e.target.closest('.toggle');
    if (toggle) {
      const li = toggle.closest('li');
      const idx = indexOfLi(li);
      todos[idx].completed = toggle.checked;
      save();
      render();
    }
  });

  todoList.addEventListener('click', (e) => {
    const destroy = e.target.closest('.destroy');
    if (destroy) {
      const li = destroy.closest('li');
      const idx = indexOfLi(li);
      todos.splice(idx, 1);
      save();
      render();
    }
  });

  todoList.addEventListener('dblclick', (e) => {
    const label = e.target.closest('label');
    if (label) {
      const li = label.closest('li');
      li.classList.add('editing');
      const edit = li.querySelector('.edit');
      edit.focus();
    }
  });

  todoList.addEventListener('keydown', (e) => {
    const edit = e.target.closest('.edit');
    if (!edit) return;
    if (e.key === 'Enter' || e.keyCode === ENTER_KEY) {
      commitEdit(edit);
    } else if (e.key === 'Escape' || e.keyCode === ESCAPE_KEY) {
      const li = edit.closest('li');
      li.classList.remove('editing');
      render();
    }
  });

  todoList.addEventListener('focusout', (e) => {
    const edit = e.target.closest('.edit');
    if (!edit) return;
    const li = edit.closest('li');
    if (!li.isConnected || !li.classList.contains('editing')) return;
    commitEdit(edit);
  });

  // Mark all as complete
  toggleAll.addEventListener('change', () => {
    const allCompleted = toggleAll.checked;
    todos.forEach((t) => { t.completed = allCompleted; });
    save();
    render();
  });

  // Clear completed
  clearCompleted.addEventListener('click', () => {
    todos = todos.filter((t) => !t.completed);
    save();
    render();
  });

  // Routing
  window.addEventListener('hashchange', () => {
    filter = routeFromHash();
    render();
  });

  render();
  newTodo.focus();
})();

const assert = require('node:assert');
const path = require('node:path');
const fs = require('node:fs');
const { Given, When, Then } = require('@cucumber/cucumber');
const { checkReconcile } = require('../reconcile_safety');

// ---- helpers ---------------------------------------------------------------

function liItems() {
  return Array.from(this.document.querySelectorAll('.todo-list li'));
}
function firstLi() {
  const items = liItems.call(this);
  assert(items.length >= 1, 'expected at least one todo item in .todo-list');
  return items[0];
}
function findLiByLabel(label) {
  const li = liItems.call(this).find((el) => el.querySelector('label').textContent === label);
  assert(li, `expected a todo item with label "${label}"`);
  return li;
}
function editInputOf(li) {
  const el = li.querySelector('.edit');
  assert(el, 'expected an .edit input on the todo item');
  return el;
}
function dispatchKey(win, el, key) {
  el.dispatchEvent(new win.KeyboardEvent('keydown', { bubbles: true, cancelable: true, key }));
}
function clickToggle(win, li) {
  const t = li.querySelector('.toggle');
  assert(t, 'expected a .toggle input on the todo item');
  t.checked = !t.checked;
  t.dispatchEvent(new win.Event('change', { bubbles: true }));
}
function persisted(key) {
  const raw = this.window.localStorage.getItem(key);
  assert(raw !== null, `expected localStorage key "${key}" to exist`);
  return JSON.parse(raw);
}
function parseValue(raw) {
  if (raw === 'true') return true;
  if (raw === 'false') return false;
  const m = /^"([\s\S]*)"$/.exec(raw);
  return m ? m[1] : raw;
}

// ---- given -----------------------------------------------------------------

Given('the app is loaded', function () {
  assert(this.document, 'verification support: app was not loaded');
});

Given('the app has the following todos:', async function (dataTable) {
  const todos = dataTable.hashes().map((row, i) => ({
    id: i + 1,
    title: row.title,
    completed: row.completed === 'true',
  }));
  await this.seedTodos(todos);
});

Given('the app is reloaded', async function () {
  await this.reloadApp();
});

// ---- when ------------------------------------------------------------------

When('the user types {string} into {string}', function (text, selector) {
  const el = this.document.querySelector(selector);
  assert(el, `expected element matching ${selector}`);
  el.value = text;
  el.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('the user presses Enter in {string}', function (selector) {
  const el = this.document.querySelector(selector);
  assert(el, `expected element matching ${selector}`);
  dispatchKey(this.window, el, 'Enter');
});

When('the user presses Enter in the edit input of the first todo item', function () {
  dispatchKey(this.window, editInputOf(firstLi.call(this)), 'Enter');
});

When('the user presses Enter in the edit input of the todo item with label {string}', function (label) {
  dispatchKey(this.window, editInputOf(findLiByLabel.call(this, label)), 'Enter');
});

When('the user presses Escape in {string}', function (selector) {
  const el = this.document.querySelector(selector);
  assert(el, `expected element matching ${selector}`);
  dispatchKey(this.window, el, 'Escape');
});

When('the user presses Escape in the edit input of the first todo item', function () {
  dispatchKey(this.window, editInputOf(firstLi.call(this)), 'Escape');
});

When('the user clicks {string}', function (selector) {
  const el = this.document.querySelector(selector);
  assert(el, `expected element matching ${selector}`);
  if (selector === '#toggle-all') {
    el.checked = !el.checked;
    el.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  } else {
    el.dispatchEvent(new this.window.Event('click', { bubbles: true }));
  }
});

When('the user clicks the toggle of the first todo item', function () {
  clickToggle(this.window, firstLi.call(this));
});

When('the user clicks the toggle of the second todo item', function () {
  const items = liItems.call(this);
  assert(items.length >= 2, 'expected at least two todo items');
  clickToggle(this.window, items[1]);
});

When('the user clicks the toggle of the todo item with label {string}', function (label) {
  clickToggle(this.window, findLiByLabel.call(this, label));
});

When('the user clicks the destroy button of the first todo item', function () {
  const li = firstLi.call(this);
  const btn = li.querySelector('.destroy');
  assert(btn, 'expected a .destroy button on the todo item');
  btn.dispatchEvent(new this.window.Event('click', { bubbles: true }));
});

When('the user double-clicks the label of the first todo item', function () {
  const label = firstLi.call(this).querySelector('label');
  label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
});

When('the user double-clicks the label of the todo item with label {string}', function (label) {
  const l = findLiByLabel.call(this, label).querySelector('label');
  l.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
});

When('the user sets the edit input of the first todo item to {string}', function (text) {
  editInputOf(firstLi.call(this)).value = text;
});

When('the user sets the edit input of the todo item with label {string} to {string}', function (label, text) {
  editInputOf(findLiByLabel.call(this, label)).value = text;
});

When('the edit input of the first todo item loses focus', function () {
  editInputOf(firstLi.call(this)).blur();
});

When('the user navigates to {string}', function (hash) {
  this.navigate(hash);
});

// ---- then ------------------------------------------------------------------

Then('the element with id {string} is hidden', function (id) {
  const el = this.document.getElementById(id);
  assert(el, `expected element with id "${id}"`);
  assert(el.hidden === true, `expected #${id} to be hidden`);
});

Then('{string} is hidden', function (selector) {
  const el = this.document.querySelector(selector);
  assert(el, `expected element matching ${selector}`);
  assert(el.hidden === true, `expected ${selector} to be hidden`);
});

Then('{string} is focused', function (selector) {
  const el = this.document.querySelector(selector);
  assert(el, `expected element matching ${selector}`);
  assert(this.document.activeElement === el, `expected ${selector} to be focused`);
});

Then('the {string} input value is empty', function (selector) {
  const el = this.document.querySelector(selector);
  assert(el, `expected element matching ${selector}`);
  assert(el.value === '', `expected ${selector} value to be empty, got "${el.value}"`);
});

Then(/^(.+) contains exactly (\d+) todo items?\.?$/, function (selector, n) {
  const sel = selector.replace(/^"|"$/g, '');
  const count = this.document.querySelectorAll(`${sel} li`).length;
  assert.strictEqual(count, n, `expected ${sel} to contain exactly ${n} todo items, got ${count}`);
});

Then('the first todo item\'s label reads {string}', function (label) {
  const text = firstLi.call(this).querySelector('label').textContent;
  assert.strictEqual(text, label, `expected first todo item label to read "${label}", got "${text}"`);
});

Then('the remaining todo item\'s label reads {string}', function (label) {
  const items = liItems.call(this);
  assert.strictEqual(items.length, 1, `expected exactly one remaining todo item, got ${items.length}`);
  const text = items[0].querySelector('label').textContent;
  assert.strictEqual(text, label, `expected remaining label to read "${label}", got "${text}"`);
});

Then('the first todo item has class {string}', function (cls) {
  assert(firstLi.call(this).classList.contains(cls), `expected first todo item to have class "${cls}"`);
});

Then('the first todo item does not have class {string}', function (cls) {
  assert(!firstLi.call(this).classList.contains(cls), `expected first todo item not to have class "${cls}"`);
});

Then('no todo item has class {string}', function (cls) {
  const withClass = liItems.call(this).filter((li) => li.classList.contains(cls));
  assert.strictEqual(withClass.length, 0, `expected no todo item to have class "${cls}", found ${withClass.length}`);
});

Then('every todo item has class {string}', function (cls) {
  const items = liItems.call(this);
  assert(items.length > 0, 'expected at least one todo item');
  const all = items.every((li) => li.classList.contains(cls));
  assert(all, `expected every todo item to have class "${cls}"`);
});

Then('the first todo item\'s edit input value is {string}', function (value) {
  const v = editInputOf(firstLi.call(this)).value;
  assert.strictEqual(v, value, `expected edit input value "${value}", got "${v}"`);
});

Then('the edit input of the first todo item is focused', function () {
  const el = editInputOf(firstLi.call(this));
  assert.strictEqual(this.document.activeElement, el, 'expected the first todo item\'s edit input to be focused');
});

Then(/^the first todo item's stored "([^"]*)" value is (.+)$/, function (key, raw) {
  const item = persisted.call(this, 'todos-vanillajs')[0];
  assert.strictEqual(item[key], parseValue(raw), `expected stored ${key} to be ${raw}`);
});

Then('the {string} reads {string}', function (selector, text) {
  const el = this.document.querySelector(selector);
  assert(el, `expected element matching ${selector}`);
  assert.strictEqual(el.textContent.trim(), text, `expected ${selector} to read "${text}", got "${el.textContent.trim()}"`);
});

Then('the {string} contains the text {string}', function (selector, text) {
  const el = this.document.querySelector(selector);
  assert(el, `expected element matching ${selector}`);
  assert.strictEqual(el.textContent, text, `expected ${selector} to contain the text "${text}", got "${el.textContent}"`);
});

Then('{string} is checked', function (selector) {
  const el = this.document.querySelector(selector);
  assert(el, `expected element matching ${selector}`);
  assert.strictEqual(el.checked, true, `expected ${selector} to be checked`);
});

Then('{string} is not checked', function (selector) {
  const el = this.document.querySelector(selector);
  assert(el, `expected element matching ${selector}`);
  assert.strictEqual(el.checked, false, `expected ${selector} to be unchecked`);
});

Then('the todo item with label {string} is visible', function (label) {
  const li = findLiByLabel.call(this, label);
  assert.notStrictEqual(li.style.display, 'none', `expected todo item "${label}" to be visible`);
});

Then('the todo item with label {string} is hidden', function (label) {
  const li = findLiByLabel.call(this, label);
  assert.strictEqual(li.style.display, 'none', `expected todo item "${label}" to be hidden`);
});

Then('the {string} has href {string}', function (selector, href) {
  const el = this.document.querySelector(selector);
  assert(el, `expected element matching ${selector}`);
  assert.strictEqual(el.getAttribute('href'), href, `expected ${selector} href "${href}", got "${el.getAttribute('href')}"`);
});

// ---- dom identity ----------------------------------------------------------
// These steps record the live <li> nodes a scenario holds across an interaction and
// later assert those exact nodes are still attached, proving the app mutated the list
// in place rather than re-rendering it.

function recordedItems() {
  const items = this._recordedItems;
  assert(Array.isArray(items), 'no recorded todo-list item elements — call "the user records the current todo-list item elements" first');
  return items;
}

When('the user records the current todo-list item elements', function () {
  this._recordedItems = Array.from(this.document.querySelectorAll('.todo-list li'));
});

Then('the recorded todo-list item elements are still attached to the document', function () {
  const items = recordedItems.call(this);
  assert(items.length > 0, 'expected at least one recorded todo-list item element');
  items.forEach((el, i) => {
    assert.strictEqual(el.isConnected, true, `recorded todo-list item element at index ${i + 1} is no longer attached to the document`);
  });
});

Then('the first recorded todo-list item element has class {string}', function (cls) {
  assert(recordedItems.call(this)[0].classList.contains(cls), `expected first recorded todo-list item element to have class "${cls}"`);
});

Then('the first recorded todo-list item element does not have class {string}', function (cls) {
  assert(!recordedItems.call(this)[0].classList.contains(cls), `expected first recorded todo-list item element not to have class "${cls}"`);
});

Then('every recorded todo-list item element has class {string}', function (cls) {
  const items = recordedItems.call(this);
  assert(items.length > 0, 'expected at least one recorded todo-list item element');
  const all = items.every((li) => li.classList.contains(cls));
  assert(all, `expected every recorded todo-list item element to have class "${cls}"`);
});

Then('no recorded todo-list item element has class {string}', function (cls) {
  const items = recordedItems.call(this);
  const withClass = items.filter((li) => li.classList.contains(cls));
  assert.strictEqual(withClass.length, 0, `expected no recorded todo-list item element to have class "${cls}", found ${withClass.length}`);
});

Then('the recorded todo-list item element at index {int} is still attached to the document', function (index) {
  const items = recordedItems.call(this);
  const el = items[index - 1];
  assert(el, `expected a recorded todo-list item element at index ${index}`);
  assert.strictEqual(el.isConnected, true, `recorded todo-list item element at index ${index} is no longer attached to the document`);
});

// ---- persistence -----------------------------------------------------------

Then('localStorage {string} contains {int} item', function (key, n) {
  const arr = persisted.call(this, key);
  assert.ok(Array.isArray(arr), `expected ${key} to be a JSON array`);
  assert.strictEqual(arr.length, n, `expected ${key} to contain ${n} item(s), got ${arr.length}`);
});

Then('localStorage {string} contains {int} items', function (key, n) {
  const arr = persisted.call(this, key);
  assert.ok(Array.isArray(arr), `expected ${key} to be a JSON array`);
  assert.strictEqual(arr.length, n, `expected ${key} to contain ${n} item(s), got ${arr.length}`);
});

Then('the persisted item at index {int} has title {string}', function (index, title) {
  const item = persisted.call(this, 'todos-vanillajs')[index];
  assert.strictEqual(item.title, title, `expected persisted item ${index} title "${title}", got "${item.title}"`);
});

Then(/^the persisted item at index (\d+) has completed (.+)$/, function (index, raw) {
  const item = persisted.call(this, 'todos-vanillajs')[Number(index)];
  assert.strictEqual(item.completed, parseValue(raw), `expected persisted item ${index} completed ${raw}`);
});

Then('localStorage {string} is a JSON array', function (key) {
  const arr = persisted.call(this, key);
  assert.ok(Array.isArray(arr), `expected ${key} to be a JSON array`);
});

Then('each item in localStorage {string} conforms to the {string} schema in {string}', function (key, _schemaName, _scantlingPath) {
  const arr = persisted.call(this, key);
  assert.ok(Array.isArray(arr), `expected ${key} to be a JSON array`);
  const allowed = new Set(['id', 'title', 'completed']);
  arr.forEach((item, i) => {
    assert.ok(item && typeof item === 'object' && !Array.isArray(item), `item ${i} is not an object`);
    const keys = Object.keys(item);
    assert.strictEqual(keys.length, 3, `item ${i} has ${keys.length} keys, expected exactly id, title, completed`);
    keys.forEach((k) => {
      assert.ok(allowed.has(k), `item ${i} has unexpected key "${k}"`);
    });
    assert.ok(typeof item.id === 'number' || typeof item.id === 'string', `item ${i} id is not a number or string`);
    assert.strictEqual(typeof item.title, 'string', `item ${i} title is not a string`);
    assert.strictEqual(typeof item.completed, 'boolean', `item ${i} completed is not a boolean`);
  });
});

Then(/^the persisted item at index (\d+) has exactly the keys (.+)$/, function (index, keysRaw) {
  const item = persisted.call(this, 'todos-vanillajs')[Number(index)];
  const expected = keysRaw.split('", "').map((s) => s.replace(/^"|"$/g, '')).sort();
  const actual = Object.keys(item).sort();
  assert.deepStrictEqual(actual, expected, `expected item ${index} keys [${expected}], got [${actual}]`);
});

// ---- empty-edit commit reconcile conformance (source check) ------------------
// happy-dom never throws on removeChild of a detached node, so this defect cannot be
// reproduced as a runtime assertion. QM authors a static source check that pins the
// reconcile's behaviour: it never removes a list element that is not a current child
// of the todo list. These steps are verification support; the product seam they
// exercise (render) is already planked.

Given('the app source at {string}', function (relPath) {
  const ROOT = path.resolve(__dirname, '..', '..', '..');
  const full = path.join(ROOT, relPath);
  assert(fs.existsSync(full), `verification support: app source not found at ${full}`);
  this.appSourcePath = relPath;
  this.appSource = fs.readFileSync(full, 'utf8');
});

When('the empty-edit commit reconcile is checked for a detached-node removeChild', function () {
  assert(this.appSource != null, 'verification support: load the app source first with "the app source at"');
  this.reconcileReport = checkReconcile(this.appSource);
});

Then('the reconcile never removes a list element that is not a current child of the todo list', function () {
  const report = this.reconcileReport;
  assert(report && report.ok === true,
    `reconcile safety check failed: ${report ? report.reason : 'check was not run'}`);
});

'use strict';

// Conformance verification support: statically verify the todo-list reconcile never
// removes a list element that is not a current child of the list.
//
// happy-dom never throws on removeChild of a detached node, so this defect cannot be
// reproduced as a runtime assertion in the harness. The Captain pinned it as a
// @conformance source check instead: the reconcile (in js/app.js) must guard every
// `todoList.removeChild(child)` with a current-child check (todoList.contains(child),
// child.isConnected, or child.parentNode === todoList) so a re-entrant edit-commit path
// cannot call removeChild on a node already detached from the list.
//
// The checker reads js/app.js as source and asserts the structural property. It is owned
// verification support under QM, not a Captain-owned scantling file: it asserts real
// structure (the source's guard), not a spied call.

function matchBracePair(src, openIdx) {
  let depth = 0;
  for (let i = openIdx; i < src.length; i++) {
    const ch = src[i];
    if (ch === '{') depth++;
    else if (ch === '}') {
      if (--depth === 0) return i;
    }
  }
  return -1;
}

function findListVar(source) {
