'use strict';

// Conformance verification support: statically verify two linked properties of the
// todo-list edit-commit path in js/app.js.
//
//   1. Defense in depth: the reconcile (render) must only ever call
//      `todoList.removeChild(child)` on a node that is a current child of the list
//      (guarded by `todoList.contains(child)`, `child.isConnected`, or
//      `child.parentNode === todoList`).
//
//   2. Root cause: the empty-edit commit (commitEdit, when the trimmed title is the
//      empty string) must END the item's editing state before the reconcile runs.
//      A real browser fires a blur/focusout on the removed edit input DURING the
//      list-element removal (removeChild), while the <li> is still connected and
//      still carries the `editing` class. The focusout handler guards re-entry with
//      `!li.classList.contains('editing')`; if the empty-edit branch never clears
//      that class, the focusout re-enters commitEdit, render runs a second time, and
//      a nested removeChild detaches the node before the outer removeChild completes,
//      raising NotFoundError in a real browser.
//
// happy-dom never throws on removeChild of a detached node and never fires a blur
// during removeChild, so this defect cannot be reproduced as a runtime assertion in
// the harness. The Captain pins it as a @conformance source check instead.
//
// The checker reads js/app.js as source and asserts the structural properties. It is
// owned verification support under QM, not a Captain-owned scantling file: it asserts
// real structure (the source's guard and the editing-state reset), not a spied call.

function matchBracePair(src, openIdx) {
  let depth = 0;
  for (let i = openIdx; i < src.length; i++) {
    const ch = src[i];
    if (ch === '{') depth++;
    else if (ch === '}') {
      if (--depth === 0) return i;
    }
  }
  return -1;
}

function extractFunction(source, name) {
  const m = new RegExp(`(?:const|let|var|function)\s+${name}\s*=\s*\([^)]*\)\s*=>\s*\{`).exec(source);
  if (!m) return null;
  const open = source.indexOf('{', m.index);
  const close = matchBracePair(source, open);
  if (close === -1) return null;
  return source.slice(open, close + 1);
}

function findEmptyEditBranch(fnBody) {
  // Locate `if (title === '') { ... }` (title = edit.value.trim()). Return the index of
  // the `if` token and the brace body, or null if there is no empty-title branch.
  const m = /if\s*\(\s*title\s*===\s*(''|""\s*)\s*\)\s*\{/.exec(fnBody);
  if (!m) return null;
  const open = fnBody.indexOf('{', m.index);
  const close = matchBracePair(fnBody, open);
  if (close === -1) return null;
  return { start: m.index, body: fnBody.slice(open, close + 1) };
}


